"""Generate the plan 05 gap-analysis deliverables from one data set.

`gap-register.md`, `coverage-matrix.md`, `technical-gap-map.md`,
`closure-roadmap.md`, and `decisions-needed.md` in this folder are **generated by
this script** from the YAML under `../data/`: `gaps.yaml`, `decisions.yaml` and
`design-coverage.yaml`. Editing a generated document by hand is reverted the next time
this runs; edit the data and re-run instead.

    python docs/mission/gap-analysis/tools/gen_gaps.py
    python docs/mission/gap-analysis/tools/gen_gaps.py --base origin/main

The second form also refuses a change that edits or removes history merged on the
base: a gap's status is the status of its last history entry, so rewriting an old
entry would rewrite what the register said at the time.

The other inputs are the plan 04 capability documents in `../../capabilities/`. The
script is deterministic: with the same inputs it rewrites the five documents byte for
byte, so a clean re-run is also the check that a hand edit has not crept in.

Lives in the repository rather than in a session scratchpad so that the next change
to the register can find it -- CLAUDE.md tells whoever edits the register to prefer
the generator over the table.
"""

import datetime
import re
import subprocess
import sys
from pathlib import Path

import yaml

# .../docs/mission/gap-analysis/tools/gen_gaps.py -> .../docs
ROOT = Path(__file__).resolve().parents[3]
CAPS_DIR = ROOT / "mission" / "capabilities"
OUT = ROOT / "mission" / "gap-analysis"
DATE = "2026-09-04"

# ---------------------------------------------------------------- inputs
tax = (CAPS_DIR / "capability-taxonomy.md").read_text(encoding="utf-8")
cap_names = {}
for m in re.finditer(r"^\| (CAP-\d\.\d+) \| (.+?) \|$", tax, re.M):
    cap_names[m.group(1)] = m.group(2)

thread_rows = (CAPS_DIR / "capability-to-thread-matrix.md").read_text(encoding="utf-8")
reach = {}
for line in thread_rows.splitlines():
    m = re.match(r"^\| (CAP-\d\.\d+) [^|]*\|(.*)\|$", line)
    if m:
        cells = [c.strip() for c in m.group(2).split("|")]
        reach[m.group(1)] = sum(1 for c in cells if c)

crate_rows = (CAPS_DIR / "capability-to-crate-matrix.md").read_text(encoding="utf-8")
impl_cov = {}
for line in crate_rows.splitlines():
    m = re.match(r"^\| (CAP-\d\.\d+) [^|]*\| (.*?) \| (\w+)", line)
    if m:
        impl_cov[m.group(1)] = m.group(3)

short = {}
for line in thread_rows.splitlines():
    m = re.match(r"^\| (CAP-\d\.\d+) (.+?) \|", line)
    if m:
        short[m.group(1)] = m.group(2).strip()

# ---------------------------------------------------------------- data
# The gaps, the decisions and the design coverage are YAML under `../data/`. They lived
# in this file as Python literals until 2026-09-16, where a status column and the prose
# beside it drifted apart often enough to be a recorded failure mode; now a gap has no
# status field at all, only a history whose last entry is the status.
DATA = OUT / "data"
DATA_REL = "docs/mission/gap-analysis/data"
REPO = ROOT.parent
STATUSES = ("Open", "Planned", "In progress", "Closed")
DESIGN_COVERAGE = ("full", "partial", "none", "planned")
GAP_FIELDS = ("id", "name", "type", "caps", "layer", "sev", "effort", "target", "owner",
              "deps", "impact", "evidence", "action", "ref", "history")
DECISION_FIELDS = ("id", "decision", "question", "raised_in", "decider", "unblocks",
                   "resolved", "amended", "outcome")
# A history note written after the data left this file is short: the explanation belongs
# in a `docs/record/` item or a pull request, and the note links it.
MIGRATED = "2026-09-16"
NOTE_WORDS = 120
_ISO = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _iso(v):
    return v.isoformat() if isinstance(v, (datetime.date, datetime.datetime)) else v


def _entries(name, text):
    raw = yaml.safe_load(text)
    if not isinstance(raw, list) or not all(isinstance(e, dict) for e in raw):
        raise SystemExit(f"{DATA_REL}/{name}: expected a list of mappings")
    return raw


def _load_gaps(text):
    gaps, problems = [], []
    for e in _entries("gaps.yaml", text):
        gid = e.get("id", "?")
        if "status" in e:
            problems.append(f"{gid}: a gap has no status field; append a history entry instead")
        if "desc" in e:
            problems.append(f"{gid}: a gap has no desc field; its history notes carry the narrative")
        extra = sorted(set(e) - set(GAP_FIELDS) - {"status", "desc"})
        missing = [k for k in GAP_FIELDS if k not in e]
        if extra or missing:
            problems.append(f"{gid}: unknown fields {extra}, missing fields {missing}")
            continue
        g = dict(e)
        g["ref"] = g["ref"] or ""
        g["history"] = [{k: _iso(v) for k, v in h.items()} for h in (e["history"] or [])]
        if not g["history"]:
            problems.append(f"{gid}: history is empty; a gap starts with one entry")
            continue
        last = None
        for i, h in enumerate(g["history"]):
            where = f"{gid} history[{i}]"
            if set(h) != {"date", "status", "note"}:
                problems.append(f"{where}: an entry has exactly date, status and note")
                continue
            if not (isinstance(h["date"], str) and _ISO.match(h["date"])):
                problems.append(f"{where}: date is YYYY-MM-DD")
            elif last and h["date"] < last:
                problems.append(f"{where}: dates run oldest first; {h['date']} follows {last}")
            else:
                last = h["date"]
            if h["status"] not in STATUSES:
                problems.append(f"{where}: status is one of {', '.join(STATUSES)}")
            if not isinstance(h["note"], str) or not h["note"].strip():
                problems.append(f"{where}: a note says what changed")
            elif h["date"] > MIGRATED and len(h["note"].split()) > NOTE_WORDS:
                problems.append(f"{where}: {len(h['note'].split())} words; keep a note to "
                                f"{NOTE_WORDS} and link a docs/record item for the rest")
        if g["type"] not in ("Mission", "Technical"):
            problems.append(f"{gid}: type is Mission or Technical")
        if g["effort"] not in ("S", "M", "L", "XL"):
            problems.append(f"{gid}: effort is S, M, L or XL")
        if not (isinstance(g["sev"], int) and 1 <= g["sev"] <= 5):
            problems.append(f"{gid}: sev is 1 to 5")
        g["status"] = g["history"][-1]["status"]
        gaps.append(g)
    return gaps, problems


def _load_decisions(text):
    decs, problems = [], []
    for e in _entries("decisions.yaml", text):
        did = e.get("id", "?")
        extra = sorted(set(e) - set(DECISION_FIELDS))
        missing = [k for k in DECISION_FIELDS if k not in e and k not in ("resolved", "amended")]
        if extra or missing:
            problems.append(f"{did}: unknown fields {extra}, missing fields {missing}")
            continue
        d = dict(e)
        d["resolved"] = _iso(d.get("resolved"))
        d["amended"] = [_iso(x) for x in (d.get("amended") or [])]
        if d["resolved"] is not None and not _ISO.match(str(d["resolved"])):
            problems.append(f"{did}: resolved is YYYY-MM-DD")
        if d["amended"] and d["resolved"] is None:
            problems.append(f"{did}: an open decision has no amendments")
        if d["amended"] != sorted(d["amended"]) or (d["amended"] and d["resolved"] and d["amended"][0] < d["resolved"]):
            problems.append(f"{did}: amendment dates run oldest first and follow the resolution")
        if d["resolved"] is None:
            d["status"] = "Open"
        else:
            d["status"] = f"Resolved {d['resolved']}"
            if d["amended"]:
                dates = d["amended"]
                joined = dates[0] if len(dates) == 1 else ", ".join(dates[:-1]) + " and " + dates[-1]
                d["status"] += f", amended {joined}"
        d["outcome"] = d.get("outcome") or ""
        decs.append(d)
    return decs, problems


def _git_show(ref, name):
    r = subprocess.run(["git", "show", f"{ref}:{DATA_REL}/{name}"], cwd=REPO,
                       capture_output=True, text=True, encoding="utf-8")
    return r.stdout if r.returncode == 0 else None


def _append_only(ref, gaps, decs):
    """Merged history is never rewritten: each base entry survives unchanged in HEAD."""
    problems = []
    base_gaps_text = _git_show(ref, "gaps.yaml")
    if base_gaps_text is not None:
        base_gaps, _ = _load_gaps(base_gaps_text)
        head = {g["id"]: g for g in gaps}
        for b in base_gaps:
            h = head.get(b["id"])
            if h is None:
                problems.append(f"{b['id']}: removed; gap ids are never removed or reused")
                continue
            n = len(b["history"])
            if h["history"][:n] != b["history"]:
                problems.append(f"{b['id']}: a history entry merged on {ref} was edited or removed")
            for i, e in enumerate(h["history"][n:], start=n):
                # An entry dated after MIGRATED was already held to the limit on load.
                if e["date"] <= MIGRATED and len(e["note"].split()) > NOTE_WORDS:
                    problems.append(f"{b['id']} history[{i}]: new notes are at most {NOTE_WORDS} words")
        base_ids = {b["id"] for b in base_gaps}
        for g in gaps:
            if g["id"] not in base_ids:
                for i, e in enumerate(g["history"]):
                    if e["date"] <= MIGRATED and len(e["note"].split()) > NOTE_WORDS:
                        problems.append(f"{g['id']} history[{i}]: new notes are at most {NOTE_WORDS} words")
    base_dec_text = _git_show(ref, "decisions.yaml")
    if base_dec_text is not None:
        base_decs, _ = _load_decisions(base_dec_text)
        head = {d["id"]: d for d in decs}
        for b in base_decs:
            h = head.get(b["id"])
            if h is None:
                problems.append(f"{b['id']}: removed; decision ids are never removed or reused")
                continue
            if b["resolved"] is not None and h["resolved"] != b["resolved"]:
                problems.append(f"{b['id']}: its resolution date merged on {ref} changed")
            if h["amended"][: len(b["amended"])] != b["amended"]:
                problems.append(f"{b['id']}: an amendment date merged on {ref} changed")
    return problems


G, _gap_problems = _load_gaps((DATA / "gaps.yaml").read_text(encoding="utf-8"))
_decs, _dec_problems = _load_decisions((DATA / "decisions.yaml").read_text(encoding="utf-8"))
_cov = _entries("design-coverage.yaml", (DATA / "design-coverage.yaml").read_text(encoding="utf-8"))
_cov_problems = [f"{c.get('capability')}: design is one of {', '.join(DESIGN_COVERAGE)}"
                 for c in _cov if c.get("design") not in DESIGN_COVERAGE]
_problems = _gap_problems + _dec_problems + _cov_problems
if "--base" in sys.argv:
    _problems += _append_only(sys.argv[sys.argv.index("--base") + 1], G, _decs)
if _problems:
    raise SystemExit("gap-analysis data:\n  " + "\n  ".join(_problems))

design = {c["capability"]: (c["design"], c["evidence"]) for c in _cov}
decisions = [(d["id"], d["decision"], d["question"], d["raised_in"], d["decider"], d["unblocks"])
             for d in _decs]
outcomes = {d["id"]: (d["status"], d["outcome"]) for d in _decs}


def narrative(g):
    """Every history note of a gap, oldest first, as one paragraph."""
    return " ".join(h["note"] for h in g["history"])


def history_lines(g):
    out = ["- History:"]
    for h in g["history"]:
        lines = h["note"].split("\n")
        body = lines[0] + "".join("\n" + ("    " + l if l else "") for l in lines[1:])
        out.append(f"  - {h['date']}, {h['status']}: {body}")
    return out


# ---------------------------------------------------------------- derived

import re as _re
_REL = [
 (r"`gungnir-capabilities\.md", "`../../gungnir-capabilities.md"),
 (r"`verification-capability-table\.md", "`../../verification-capability-table.md"),
 (r"`performance-budgets\.md", "`../../performance-budgets.md"),
 (r"`release-governance\.md", "`../../release-governance.md"),
 (r"`gungnir-api-v1\.md", "`../../gungnir-api-v1.md"),
 (r"`architecture\.md", "`../../architecture.md"),
 (r"`ARCHITECTURE\.md", "`../../../ARCHITECTURE.md"),
 (r"`CONTRIBUTING\.md", "`../../../CONTRIBUTING.md"),
 (r"`docs/design/", "`../../design/"),
 (r"`docs/plans/", "`../../plans/"),
 (r"`docs/ux/", "`../../ux/"),
 (r"`rust-ui-tech-stack-summary\.md", "`../../rust-ui-tech-stack-summary.md"),
 (r"`mission/capabilities/", "`../capabilities/"),
 (r"`mission/", "`../"),
 (r"`mission-analysis\.md", "`../mission-analysis.md"),
]
def rel(t):
    for a, b in _REL:
        t = _re.sub(a, b, t)
    return t
for _g in G:
    for _k in ("evidence", "impact", "action", "ref"):
        _g[_k] = rel(_g[_k])
    for _h in _g["history"]:
        _h["note"] = rel(_h["note"])
decisions = [tuple(rel(x) for x in d) for d in decisions]
EFFORT_RANK = {"S": 1, "M": 2, "L": 3, "XL": 4}
for g in G:
    g["reach"] = max(reach[c] for c in g["caps"])
    g["priority"] = g["sev"] * g["reach"]
# Identifiers must be unique. `README.md` under "Identifiers": "`GAP-nnn`: a gap.
# Stable; never reused. New gaps are appended." -- and `D-nn` is stable likewise. Two
# branches that each append a gap pick the same next number, and git merges them with no
# conflict, because the two `gap(...)` calls sit at different offsets. Nothing below
# catches that: the dependency, cycle, ordering and coverage checks all read `ids` and
# `dids` as sets, which collapse a duplicate, so the register renders two summary rows
# and two entry blocks under the one identifier -- and CI's regenerate-and-diff still
# passes, because the generator stays deterministic. It is not reliably loud either: two
# duplicates in the same target increment do starve `closure-roadmap.md`'s wave below
# into a bare `IndexError`, but only after three of the five documents are written, while
# two in different increments write all five and exit 0. So count the ids here, before
# they are collected. Four collisions so far: GAP-090 (and again on the GAP-094 it was
# renumbered to), GAP-097, and GAP-102 on 2026-09-09.
def dupes(seq):
    seen, dup = set(), []
    for x in seq:
        if x in seen and x not in dup:
            dup.append(x)
        seen.add(x)
    return dup
_dup = dupes([g["id"] for g in G])
if _dup:
    raise SystemExit(f"duplicate gap id: {', '.join(_dup)}; ids are never reused (README.md)")
_dup = dupes([d[0] for d in decisions])
if _dup:
    raise SystemExit(f"duplicate decision id: {', '.join(_dup)}; ids are never reused (README.md)")

ids = {g["id"] for g in G}
dids = {d[0] for d in decisions}
# Every decision has an outcome and every outcome has a decision. `decisions-needed.md`
# reads `outcomes[d[0]]` twice, so a decision with no outcome is a loud `KeyError` there,
# but an outcome left behind by a deleted decision renders nothing and would pass.
_no_outcome = sorted(dids - set(outcomes))
_no_decision = sorted(set(outcomes) - dids)
if _no_outcome or _no_decision:
    raise SystemExit(f"decision ids with no outcome: {_no_outcome}; "
                     f"outcome ids with no decision: {_no_decision}")
for g in G:
    for d in g["deps"]:
        assert d in ids or d in dids, (g["id"], d)
# cycle check
adj = {g["id"]: [d for d in g["deps"] if d in ids] for g in G}
state = {}
def visit(n, stack):
    if state.get(n) == 1:
        raise SystemExit(f"cycle: {stack + [n]}")
    if state.get(n) == 2:
        return
    state[n] = 1
    for m in adj[n]:
        visit(m, stack + [n])
    state[n] = 2
for n in adj:
    visit(n, [])
# targets must not precede deps' targets
order = {"I1": 1, "I2": 2, "I3": 3, "I4": 4}
byid = {g["id"]: g for g in G}
for g in G:
    for d in adj[g["id"]]:
        assert order[byid[d]["target"]] <= order[g["target"]], (g["id"], d)

caps_with_gaps = {}
for g in G:
    for c in g["caps"]:
        caps_with_gaps.setdefault(c, []).append(g["id"])
for c, (dc, _) in design.items():
    if (dc != "full" or impl_cov[c] != "full") and c not in caps_with_gaps:
        raise SystemExit(f"{c} has coverage {dc}/{impl_cov[c]} but no gap")

GENERATED = ("Generated by `tools/gen_gaps.py` from `data/`: edit the data and re-run the "
             "generator, never this file.\n")


def caplink(c):
    return f"{c} {short[c]}"

# ---------------------------------------------------------------- gap-register.md
L = []
L.append("# Gap register\n")
L.append(f"Status: first draft, {DATE}. One entry per gap between what the missions need\n"
         "(`../capabilities/`) and what Gungnir is designed and built to provide. The scoring\n"
         "scheme and the maintenance rule are in `README.md`; the decisions that gaps depend\n"
         "on are in `decisions-needed.md`. Severity, effort, and target values are the\n"
         "drafting agent's proposals for the owner and the engineering reviewer to confirm.\n")
L.append(GENERATED.rstrip("\n") + " A gap's status is the status of the last entry in its\n"
         "history, and an entry is never edited once it has merged.\n")
L.append("## Summary\n")
L.append("| Id | Gap | Type | Capability | Sev | Reach | Effort | Priority | Target | Owner | Status |")
L.append("|---|---|---|---|---|---|---|---|---|---|---|")
for g in G:
    L.append(f"| {g['id']} | {g['name']} | {g['type']} | {', '.join(g['caps'])} | {g['sev']} | {g['reach']} | {g['effort']} | {g['priority']} | {g['target']} | {g['owner']} | {g['status']} |")
n_m = sum(1 for g in G if g["type"] == "Mission"); n_t = sum(1 for g in G if g["type"] == "Technical")
L.append(f"\nCounts: {len(G)} gaps, {n_m} mission, {n_t} technical; {sum(1 for g in G if g['status']=='Planned')} already covered by a plan in `../../plans/`. "
         "Reach is the number of mission threads the capability serves (from\n`../capabilities/capability-to-thread-matrix.md`); priority is severity times reach.\n")
L.append("## Entries\n")
for g in G:
    L.append(f"**{g['id']} {g['name']}**"); L.append("")
    L.append(f"- Type: {g['type']}.")
    L.append("- Capability: " + "; ".join(caplink(c) for c in g["caps"]) + ".")
    L.extend(history_lines(g))
    L.append(f"- Evidence: {g['evidence']}.")
    L.append(f"- Severity: {g['sev']}. Reach: {g['reach']} threads. Effort: {g['effort']}. Priority: {g['priority']}.")
    L.append(f"- Impact: {g['impact']}")
    L.append(f"- Closing action: {g['action']}")
    L.append(f"- Target: {g['target']}. Owner: {g['owner']}. Status: {g['status']}.")
    if g["ref"]:
        L.append(f"- Reference: {g['ref']}.")
    if g["deps"]:
        L.append("- Depends on: " + ", ".join(g["deps"]) + ".")
    L.append("")
(OUT / "gap-register.md").write_text(rel("\n".join(L)) + "\n", encoding="utf-8", newline="\n")

# ---------------------------------------------------------------- coverage-matrix.md
L = []
L.append("# Coverage matrix\n")
L.append(f"Status: first draft, {DATE}. For each leaf capability: **design coverage** (does the\n"
         "architecture name a component responsible for every part of it: full, partial,\n"
         "none, or planned when a plan in `../../plans/` owns it) and **implementation\n"
         "coverage** (from `../capabilities/capability-to-crate-matrix.md`: full, partial,\n"
         "none), with the evidence and the gaps that follow. A capability with full design\n"
         "coverage and partial implementation has technical gaps only; anything less than\n"
         "full design coverage has at least one mission gap.\n\n"
         "Twenty-two rows reached full design coverage on 2026-09-05 through plan 11's\n"
         "design notes in `../../design/`. That set is reviewed: the engineering reviewer\n"
         "accepted the five new dependency edges, a domain reviewer checked each note against\n"
         "the mission thread step it names, and what the owner signed of it is in\n"
         "`../../signatures.md`. Full design coverage means a reviewed component is named for\n"
         "every part of the capability; implementation is what remains.\n")
L.append(GENERATED)
L.append("| Capability | Design | Implementation | Evidence | Gaps |")
L.append("|---|---|---|---|---|")
for c in cap_names:
    dc, ev = design[c]
    gl = ", ".join(caps_with_gaps.get(c, [])) or "none"
    L.append(f"| {caplink(c)} | {dc} | {impl_cov[c]} | {ev} | {gl} |")
from collections import Counter
dcount = Counter(d[0] for d in design.values()); icount = Counter(impl_cov.values())
L.append("\n## Counts\n")
L.append("| Coverage | Design | Implementation |")
L.append("|---|---|---|")
for k in ["full", "partial", "none", "planned"]:
    L.append(f"| {k} | {dcount.get(k,0)} | {icount.get(k,0)} |")
L.append("\nEvery capability whose design or implementation coverage is less than full has at\n"
         "least one gap entry; the generator refuses to write these documents otherwise.")
(OUT / "coverage-matrix.md").write_text(rel("\n".join(L)) + "\n", encoding="utf-8", newline="\n")

# ---------------------------------------------------------------- technical-gap-map.md
layers = ["Tracking core", "Service facades and wiring", "Productization: sensing and time",
          "Productization: picture and identity", "Productization: decision and policy",
          "Productization: sustainment", "Productization: security", "Deployment and API",
          "UI and data ecosystem", "Verification and governance", "Plans in execution"]
L = []
L.append("# Technical gap map\n")
L.append(f"Status: first draft, {DATE}. The technical gaps from `gap-register.md` grouped by\n"
         "architecture layer (`../../../ARCHITECTURE.md` §1 to §8), each pointing at the\n"
         "record item (`../../record/`, which was `ARCHITECTURE.md` §10) or the\n"
         "`../../verification-capability-table.md` row that tracks it. Mission gaps appear\n"
         "only in the register and the roadmap.\n")
L.append(GENERATED)
L.append("## The §10 open items of 2026-09-04 and the gaps that carried them\n")
L.append("| `ARCHITECTURE.md` §10 open item | Gaps or decisions |")
L.append("|---|---|")
sec10 = [
 ("Scope lock", "D-01"),
 ("The tracking math itself", "GAP-011, GAP-013, GAP-015, GAP-016, GAP-029"),
 ("Intercept geometry", "GAP-031"),
 ("three-d attachment", "GAP-022"),
 ("API transport libraries", "GAP-041, GAP-050"),
 ("Live protocol adapters and industry codecs", "GAP-001, GAP-010, GAP-064"),
 ("Credential mechanism", "D-02, GAP-057"),
 ("Locking the reconciliation and arbitration rules; release-governance items", "D-03, D-10"),
 ("Performance budgets", "D-04, GAP-056"),
 ("Cross-session identity correlation", "GAP-019"),
 ("`uuid` for `GlobalEntityId`", "D-11"),
]
for a, b in sec10:
    L.append(f"| {a} | {b} |")
L.append("\n## By layer\n")
for layer in layers:
    rows = [g for g in G if g["layer"] == layer and g["type"] == "Technical"]
    if not rows:
        continue
    L.append(f"### {layer}\n")
    L.append("| Gap | Capability | Sev | Effort | Target | Tracked in |")
    L.append("|---|---|---|---|---|---|")
    for g in rows:
        ref = g["ref"] or "Added to `ARCHITECTURE.md` §10 by this register"
        L.append(f"| {g['id']} {g['name']} | {', '.join(g['caps'])} | {g['sev']} | {g['effort']} | {g['target']} | {ref} |")
    L.append("")
L.append("## Integration gaps\n")
L.append("Gaps where two components exist but are not connected, found by the coverage pass:\n")
for gid in ["GAP-003", "GAP-014", "GAP-028", "GAP-053", "GAP-059"]:
    g = byid[gid]
    L.append(f"- {gid} {g['name']}: {narrative(g)}")
