# ---------------------------------------------------------------- closure-roadmap.md
L = []
L.append("# Closure roadmap\n")
L.append(f"Status: first draft, {DATE}. Gaps by target increment, ordered by priority\n"
         "(severity times reach) and then by effort, smaller first, so that within an\n"
         "increment the cheapest high-priority closures come first. Dependencies are listed\n"
         "so nothing is scheduled before what it needs; the generator checked that no gap\n"
         "targets an earlier increment than any gap it depends on and that there are no\n"
         "cycles. Increments are those of `../../gungnir-capabilities.md` §7 and the\n"
         "capability roadmap in `../capabilities/capability-roadmap.md`.\n")
L.append(GENERATED)
inc_text = {
 "I2": "Integrate real data. Closes the tracking mathematics, the data path from real sensors, and the harnesses that make everything after it measurable.",
 "I3": "Close the decision loop. Closes the allocator, geometry, asset list, policy model, queue, and the panels that let a human decide in the product.",
 "I4": "Operationalize and scale. Closes the transport and everything that waits on it: peers, handoff, failover, authentication for callers, encryption, releasability.",
}
for inc in ["I2", "I3", "I4"]:
    pool = [g for g in G if g["target"] == inc]
    pool_ids = {g["id"] for g in pool}
    done = set(); rows = []
    while len(rows) < len(pool):
        ready = [g for g in pool if g["id"] not in done and all(d not in pool_ids or d in done for d in g["deps"])]
        ready.sort(key=lambda g: (-g["priority"], EFFORT_RANK[g["effort"]], g["id"]))
        rows.append(ready[0]); done.add(ready[0]["id"])
    L.append(f"## {inc}: {inc_text[inc]}\n")
    L.append("| Order | Gap | Type | Priority | Effort | Owner | Depends on |")
    L.append("|---|---|---|---|---|---|---|")
    for i, g in enumerate(rows, 1):
        L.append(f"| {i} | {g['id']} {g['name']} | {g['type']} | {g['priority']} | {g['effort']} | {g['owner']} | {', '.join(g['deps']) or ''} |")
    L.append("")
L.append("## Critical path (rewritten 2026-09-07, in the development-status review)\n")
L.append("Every gap the previous version of this section named -- GAP-016, GAP-048, GAP-011,\n"
         "GAP-030, GAP-029, GAP-031, GAP-028, GAP-038, GAP-052, GAP-012, GAP-018, GAP-033,\n"
         "GAP-035, GAP-058, GAP-041 -- is Closed, and every decision it named (D-02, D-05,\n"
         "D-08, D-09, D-15, D-16) is Resolved. The path below is traced fresh from the\n"
         "`deps` still open in the register today, not carried forward from the section this\n"
         "replaces.")
